return items.map(item => ({
  json: {
    to: item.json.email || 'sin-correo@demo.local',
    subject: 'Bienvenido a SION UNAC',
    name: item.json.name || 'Aspirante',
    userId: item.json.userId,
    role: item.json.role,
    body: 'Hola ' + (item.json.name || 'Aspirante') + ', tu cuenta fue creada correctamente. Ya puedes iniciar sesion y completar tu inscripcion.',
    sentAt: new Date().toISOString()
  }
}));
